'use client'

import { useActionState } from 'react'

async function submitContact(prevState: string | undefined, formData: FormData) {
  'use server'

  const name = formData.get('name')
  const email = formData.get('email')
  const message = formData.get('message')

  // Server-side validation: ensure all fields are provided.
  if (!name || !email || !message) {
    return 'Please fill in all fields.'
  }

  const nameStr = String(name).trim()
  const emailStr = String(email).trim()
  const messageStr = String(message).trim()

  if (!nameStr || !emailStr || !messageStr) {
    return 'Please fill in all fields.'
  }

  // Simulate saving the contact message.
  console.log('Saving contact message:', { name: nameStr, email: emailStr, message: messageStr })

  return 'Thanks for reaching out! Your message has been received.'
}

export default function ContactForm() {
  const [state, formAction, isPending] = useActionState(submitContact, undefined)

  return (
    <div>
      <h2>Contact Us</h2>
      <form action={formAction}>
        <div>
          <label htmlFor="contact-name">Name</label>
          <input id="contact-name" name="name" placeholder="Your name" required />
        </div>
        <div>
          <label htmlFor="contact-email">Email</label>
          <input
            id="contact-email"
            name="email"
            type="email"
            placeholder="you@example.com"
            required
          />
        </div>
        <div>
          <label htmlFor="contact-message">Message</label>
          <textarea
            id="contact-message"
            name="message"
            placeholder="How can we help?"
            required
          />
        </div>
        <button type="submit" disabled={isPending}>
          {isPending ? 'Sending...' : 'Send Message'}
        </button>
        {state && <p>{state}</p>}
      </form>
    </div>
  )
}

